\set ON_ERROR_STOP on
BEGIN;
-- mission_brief v3 (owner 2026-09-03: no contact page/email; author = AI). Supersede + insert; the planner reads mission_brief.text.
UPDATE site_specs SET is_current=false, superseded_at=now() WHERE site_id='8f17eb73-fc74-4718-8371-b3125bc4e414' AND aspect='mission_brief' AND is_current;
INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, pinned, created_by)
VALUES ('8f17eb73-fc74-4718-8371-b3125bc4e414','mission_brief', jsonb_build_object('text', $v3$gamedesign.uk is about the practice of game design as it is actually done inside working studios, and it should feel like games from the first second: full of games, images and energy. It is written for people who already do this for a living, leads, producers, senior and principal designers, and for those trying to get there, and it is editorial, not a tool library. But editorial about games means the games are on the page. Every piece is built around real, published games the reader knows, described the way a player experiences them: the loot table you can feel in a roguelike, the boss fight that shipped because someone signed it off, the level whose pipeline you can read in its seams. Name the games. Show them. Where a concept is better played than read, the piece carries a small playable illustration, a live interactive demonstration embedded in the article, and links to the full tool on the sister site gamesdesign.co.uk rather than duplicating it. The sister site is the place for free calculators and the guide library and this site links to it warmly wherever a tool is the right next step; the two divide the work and should read as siblings, not competitors. This site does not publish calculators, simulators, tool pages or a guide library of its own. Imagery is game imagery: in-game scenes, characters, worlds, mechanics made visible, bold and saturated, stylised where the game is stylised. Big pictures, not pencils and paper. The look is confident and alive, closer to a games magazine than a print journal: strong colour, large game art in the heroes, generous white space around it, and display type with some swagger, on a light ground so it stays visibly different from gamesdesign.co.uk, which is a dark site, near-black with cyan accents and a sans-serif face throughout. It is not a general design blog either, so no stark white minimalism and no hot accent colour for its own sake. There is no contact page, no contact form and no email address anywhere on the site; a reader who wants the tools goes to the sister site, and that is the only outward link the site needs to offer. The site is written by an AI, a large language model, and it says so plainly: on the about page and wherever authorship would naturally be stated, the voice is an AI writing about the practice of game design for the people who do it. Do not invent a human author, a masthead, a studio background or a publication history; say what the author is. Its subject is game design and nothing wider. It is not a general design, web design or graphic design publication, and it does not stray into animation or cartoon making as a subject. Narrative design is in scope as a discipline of game design; general writing advice is not. Do not use the phrase game room or any variant of it. The site launches with real articles, not a description of what the articles will be like. A page that lists articles must list articles; a page must never explain its own brief, describe what it will contain, or say what it avoids. On money: there may in time be a paid offering for studios and design programmes. Nothing on the site should say one exists, name it, describe its features or price it, and nothing should rule one out either. Do not say the site is free, or that it does not sell anything, or otherwise define it by what it is not. Say what it is. Write for a working professional who loves games and is tired of shallow writing about them: short sentences, British English, no exclamation marks, vivid concrete detail from actual play, opinion given as opinion. Do not call anything powerful, seamless, effortless, essential or ultimate. You may name any commercially released game and describe what a player can see and feel in it; do not state its sales, budget, team size, development timeline or what its studio decided internally unless the owner has supplied that fact. Do not state numbers of any other kind, studio sizes, salaries, years of experience, reader counts, percentages, unless supplied. Do not invent named studios, named people, case studies, job titles attributed to real organisations, or quotations.$v3$), 'manual',
 'v3 2026-09-03 09:45Z, owner rulings: no contact page, no contact email, author is an AI LLM. Written BEFORE the planner claimed needs_site_plan (triaged 09:34).', true, true, 'gamedesign-uk-lane-2026-09-03');
-- evidence_base v3: ban any email address and any contact form; allow the AI author.
UPDATE site_specs SET is_current=false, superseded_at=now() WHERE site_id='8f17eb73-fc74-4718-8371-b3125bc4e414' AND aspect='evidence_base' AND is_current;
INSERT INTO site_specs (site_id, aspect, data, source, notes, is_current, pinned, created_by)
SELECT '8f17eb73-fc74-4718-8371-b3125bc4e414','evidence_base',
  (SELECT data FROM site_specs WHERE site_id='8f17eb73-fc74-4718-8371-b3125bc4e414' AND aspect='evidence_base' ORDER BY created_at DESC LIMIT 1)
  || jsonb_build_object(
    'banned_claims', (SELECT data->'banned_claims' FROM site_specs WHERE site_id='8f17eb73-fc74-4718-8371-b3125bc4e414' AND aspect='evidence_base' ORDER BY created_at DESC LIMIT 1)
      || '[{"pattern":"[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,}","reason":"owner 2026-09-03: no contact email anywhere on the site."},{"pattern":"contact (form|page)|(fill in|submit) (the|this|a) form","reason":"owner 2026-09-03: no contact page and no contact form."},{"pattern":"(our|the) (editor|editorial team|writers|staff|founder)s? (is|are|has|have|were|was)","reason":"author is an AI LLM and says so; do not imply a human masthead."}]'::jsonb,
    'writer_block', (SELECT data->>'writer_block' FROM site_specs WHERE site_id='8f17eb73-fc74-4718-8371-b3125bc4e414' AND aspect='evidence_base' ORDER BY created_at DESC LIMIT 1)
      || E'\n\nAUTHORSHIP (owner ruling 2026-09-03): the site is written by an AI, a large language model, and SAYS SO plainly on the about page and wherever authorship would naturally be stated. That is the editorial voice. Never invent a human author, an editorial team, a studio background or a publication history.\n\nCONTACT (owner ruling 2026-09-03): there is no contact page, no contact form and no email address anywhere on the site. Do not write one, offer one, or refer to one. The only outward destination the site offers is the sister site gamesdesign.co.uk for tools.'
  ), 'manual', 'v3 2026-09-03: email addresses and contact forms banned as shapes; the AI author allowed and required to be stated.', true, true, 'gamedesign-uk-lane-2026-09-03';
COMMIT;
SELECT aspect, created_at::timestamp(0), (data->>'text' ILIKE '%written by an AI%') AS v3_brief, jsonb_array_length(COALESCE(data->'banned_claims','[]'::jsonb)) AS bans FROM site_specs WHERE site_id='8f17eb73-fc74-4718-8371-b3125bc4e414' AND aspect IN ('mission_brief','evidence_base') AND is_current;
